'use client';

import { useBalances } from '@/lib/pmxt/hooks';
import { usePmxtWallet } from '@/lib/pmxt/provider';
import { formatUsd, venueLabel } from '@/lib/pmxt/format';
import { ExternalLinkIcon, SpinnerIcon } from '@/lib/pmxt/icons';

export interface BalanceCardProps {
    /** Address to show balances for; defaults to the connected wallet. */
    address?: `0x${string}`;
    className?: string;
}

/** PMXT escrow balance for an address, with a deposit/withdraw link. */
export function BalanceCard({ address, className = '' }: BalanceCardProps) {
    const wallet = usePmxtWallet();
    const resolved = address ?? wallet.address;
    const { data, error, loading } = useBalances(resolved);

    if (!resolved) {
        return (
            <section
                className={`rounded-xl border border-zinc-200/80 bg-white p-4 shadow-sm ${className}`}
            >
                <button
                    type="button"
                    onClick={() => void wallet.connect()}
                    disabled={wallet.connecting}
                    className="w-full rounded-lg bg-zinc-900 px-3 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-zinc-800 disabled:cursor-not-allowed disabled:opacity-50"
                >
                    {wallet.connecting ? 'Connecting…' : 'Connect wallet'}
                </button>
            </section>
        );
    }

    const balances = data ?? [];
    const primary = balances[0];

    return (
        <section
            className={`rounded-xl border border-zinc-200/80 bg-white p-4 shadow-sm ${className}`}
        >
            <div className="text-[11px] font-medium uppercase tracking-wide text-zinc-400">
                PMXT escrow balance
            </div>
            <div className="mt-1 font-mono text-3xl font-semibold text-zinc-950">
                {loading && !data ? (
                    <SpinnerIcon className="size-6 text-zinc-300" />
                ) : (
                    formatUsd(primary?.amount)
                )}
            </div>
            {error && <div className="mt-1 text-xs text-red-600">{error}</div>}
            {balances.length > 1 && (
                <ul className="mt-3 space-y-1 border-t border-zinc-100 pt-3">
                    {balances.map((b, i) => (
                        <li
                            key={`${b.venue ?? 'all'}-${b.currency}-${i}`}
                            className="flex items-center justify-between text-xs text-zinc-600"
                        >
                            <span>
                                {venueLabel(b.venue)}{' '}
                                <span className="uppercase text-zinc-400">
                                    {b.currency}
                                </span>
                            </span>
                            <span className="font-mono text-zinc-900">
                                {formatUsd(b.amount)}
                            </span>
                        </li>
                    ))}
                </ul>
            )}
            <div className="mt-3 flex items-center justify-end gap-2 text-xs text-zinc-500">
                <a
                    href="https://pmxt.dev/dashboard/wallet"
                    target="_blank"
                    rel="noreferrer"
                    className="inline-flex shrink-0 items-center gap-1 font-medium text-zinc-700 transition-colors hover:text-zinc-950"
                >
                    Deposit / withdraw →
                    <ExternalLinkIcon className="size-3" />
                </a>
            </div>
        </section>
    );
}
